} as const;

// Seeded randomness and noise. Deterministic for a given seed, so previews and tests repeat.

// Small fast PRNG. Returns floats in [0, 1).
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// FNV-1a 32-bit.
export function hashString(s: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

// Integer lattice hash to [-1, 1].
function latticeHash(seed: number, x: number, y = 0): number {
  let h = Math.imul(x | 0, 374761393) ^ Math.imul(y | 0, 668265263) ^ Math.imul(seed | 0, 2246822519);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return ((h >>> 0) / 4294967295) * 2 - 1;
}

function smooth(t: number): number {
  return t * t * (3 - 2 * t);
}

export function valueNoise1D(seed: number): (x: number) => number {
  return (x: number) => {
    const i = Math.floor(x);
    const f = x - i;
    const a = latticeHash(seed, i);
    const b = latticeHash(seed, i + 1);
    return a + (b - a) * smooth(f);
  };
}

export function fbm1D(seed: number, octaves = 3): (x: number) => number {
  const layers = Array.from({ length: octaves }, (_, o) => valueNoise1D(seed + o * 101));
  let norm = 0;
  for (let o = 0; o < octaves; o++) norm += 0.5 ** o;
  return (x: number) => {
    let sum = 0;
    let amp = 1;
    let freq = 1;
    for (let o = 0; o < octaves; o++) {
      sum += amp * layers[o](x * freq);
      amp *= 0.5;
      freq *= 2;
    }
    return sum / norm;
  };
}

export function valueNoise2D(seed: number): (x: number, y: number) => number {
  return (x: number, y: number) => {
    const xi = Math.floor(x);
    const yi = Math.floor(y);
    const fx = smooth(x - xi);
    const fy = smooth(y - yi);
    const a = latticeHash(seed, xi, yi);
    const b = latticeHash(seed, xi + 1, yi);
    const c = latticeHash(seed, xi, yi + 1);
    const d = latticeHash(seed, xi + 1, yi + 1);
    const top = a + (b - a) * fx;
    const bottom = c + (d - c) * fx;
    return top + (bottom - top) * fy;
  };
}

"use client";

// Canvas plumbing shared by the Charts collection. One hook gives a chart a measured host, a
// DPR-capped canvas that follows it, and a draw loop that pauses offscreen and idles when settled.

import { useCallback, useEffect, useRef, type RefObject } from "react";
import { useVisibleLoop } from "@/components/bjork-ui/_core/loop";
import { sizeCanvas, useElementSize } from "@/components/bjork-ui/_core/canvas";
import { cubicBezier, ease } from "@/components/bjork-ui/_core/motion";

export interface ChartFrame {
  ctx: CanvasRenderingContext2D;
  w: number;
  h: number;
  dt: number;
  t: number;
}

/**
 * `draw` runs inside `useVisibleLoop`. Return true to keep animating, false to go idle until `wake()`.
 * The loop root is `rootRef` (gets `data-loop`). The canvas is sized to `hostRef`.
 */
export function useChartCanvas(draw: (f: ChartFrame) => boolean) {
  const rootRef = useRef<HTMLDivElement>(null);
  const hostRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const size = useElementSize(hostRef);
  const sizeRef = useRef({ w: 0, h: 0, dpr: 1 });
  const drawRef = useRef(draw);
  useEffect(() => {
    drawRef.current = draw;
  });

  const frame = useCallback((dt: number, t: number) => {
    const canvas = canvasRef.current;
    const { w, h, dpr } = sizeRef.current;
    if (!canvas || !w || !h) return true;
    const ctx = canvas.getContext("2d");
    if (!ctx) return false;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, w, h);
    return drawRef.current({ ctx, w, h, dt, t });
  }, []);

  const { wake } = useVisibleLoop(rootRef as RefObject<HTMLElement | null>, frame);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || !size.width || !size.height) return;
    sizeRef.current = { w: size.width, h: size.height, dpr: sizeCanvas(canvas, size.width, size.height) };
    wake();
  }, [size.width, size.height, wake]);

  return { rootRef, hostRef, canvasRef, size, wake };
}

// The house ease-out for entrances, usable in rAF code.
export const easeOut = cubicBezier(...(ease.out as unknown as [number, number, number, number]));
export const easeInOut = cubicBezier(...(ease.inOut as unknown as [number, number, number, number]));

// A 45 degree hatch pattern in `color`, for counterfactual and loss regions.
const hatchCache = new Map<string, CanvasPattern | null>();
export function hatchPattern(ctx: CanvasRenderingContext2D, color: string, gap = 5, width = 1): CanvasPattern | null {
  const key = `${color}|${gap}|${width}`;
  if (hatchCache.has(key)) return hatchCache.get(key)!;
  if (typeof document === "undefined") return null;
  const tile = document.createElement("canvas");
  const s = gap * 2;
  tile.width = s * 2;
  tile.height = s * 2;
  const c = tile.getContext("2d");
  if (!c) return null;
  c.scale(2, 2);
  c.strokeStyle = color;
  c.lineWidth = width;
  c.beginPath();
  for (let k = -s; k <= s * 2; k += gap) {
    c.moveTo(k, s);
    c.lineTo(k + s, 0);
  }
  c.stroke();
  const pattern = ctx.createPattern(tile, "repeat");
  pattern?.setTransform(new DOMMatrix().scale(0.5, 0.5));
  hatchCache.set(key, pattern);
  return pattern;
}

// Rounded rect path with independent top and bottom radii (bars: round data end, square baseline).
export function roundRectPath(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  w: number,
  h: number,
  rTop: number,
  rBottom = 0,
) {
  if (w <= 0 || h <= 0) return;
  const rt = Math.min(rTop, w / 2, h / 2);
  const rb = Math.min(rBottom, w / 2, h / 2);
  ctx.moveTo(x + rt, y);
  ctx.lineTo(x + w - rt, y);
  if (rt) ctx.arcTo(x + w, y, x + w, y + rt, rt);
  ctx.lineTo(x + w, y + h - rb);
  if (rb) ctx.arcTo(x + w, y + h, x + w - rb, y + h, rb);
  ctx.lineTo(x + rb, y + h);
  if (rb) ctx.arcTo(x, y + h, x, y + h - rb, rb);
  ctx.lineTo(x, y + rt);
  if (rt) ctx.arcTo(x, y, x + rt, y, rt);
  ctx.closePath();
}

export interface PlacedLabel {
  text: string;
  x: number;
  y: number;
  /** translate percentages applied after the position, e.g. -50 to centre. */
  ax?: number;
  ay?: number;
  opacity?: number;
}

// Writes a pool of absolutely positioned label spans from the loop: text only when it changes,
// position by transform only. Unused spans hide.
export function writeLabels(els: (HTMLElement | null)[], cache: string[], items: PlacedLabel[]) {
  for (let i = 0; i < els.length; i++) {
    const el = els[i];
    if (!el) continue;
    const it = items[i];
    if (!it) {
      if (el.style.opacity !== "0") el.style.opacity = "0";
      continue;
    }
    if (cache[i] !== it.text) {
      cache[i] = it.text;
      el.textContent = it.text;
    }
    el.style.opacity = String(it.opacity ?? 1);
    el.style.transform = `translate3d(${it.x.toFixed(2)}px, ${it.y.toFixed(2)}px, 0) translate(${it.ax ?? 0}%, ${it.ay ?? -50}%)`;
  }
}

"use client";

import { useCallback, useEffect, useMemo, useRef, type RefObject } from "react";

export interface VisibleLoopOptions {
  enabled?: boolean;
  fpsCap?: number;
  rootMargin?: string;
}

/**
 * Runs `frame(dt, t)` on requestAnimationFrame while the element is near the viewport,
 * the tab is visible and `enabled` is not false. Return `false` from `frame` to go idle
 * until `wake()` is called. Writes `data-loop` on the element: running, idle or paused.
 */
export function useVisibleLoop(
  ref: RefObject<HTMLElement | null>,
  frame: (dt: number, t: number) => boolean | void,
  opts?: VisibleLoopOptions,
): { wake: () => void } {
  const enabled = opts?.enabled !== false;
  const fpsCap = opts?.fpsCap ?? 0;
  const rootMargin = opts?.rootMargin ?? "96px";

  const frameRef = useRef(frame);
  useEffect(() => {
    frameRef.current = frame;
  }, [frame]);

  const wakeRef = useRef<() => void>(() => {});
  const wake = useCallback(() => wakeRef.current(), []);

  useEffect(() => {
    const el = ref.current;
    if (!el || typeof window === "undefined") return;

    let wants = true; // false once the frame callback returns false
    let inView = false;
    let raf = 0;
    let last = 0;
    let t = 0;
    const minFrame = fpsCap > 0 ? 1000 / fpsCap : 0;

    const canRun = () => enabled && inView && document.visibilityState === "visible";
    const stop = () => {
      if (raf) cancelAnimationFrame(raf);
      raf = 0;
    };

    const update = () => {
      if (!enabled) {
        stop();
        el.dataset.loop = "paused";
        return;
      }
      if (!wants) {
        stop();
        el.dataset.loop = "idle";
        return;
      }
      if (!canRun()) {
        stop();
        el.dataset.loop = "paused";
        return;
      }
      el.dataset.loop = "running";
      if (!raf) {
        last = performance.now();
        raf = requestAnimationFrame(tick);
      }
    };

    const tick = (now: number) => {
      raf = 0;
      if (!canRun() || !wants) {
        update();
        return;
      }
      const elapsed = now - last;
      if (minFrame && elapsed < minFrame - 0.5) {
        raf = requestAnimationFrame(tick);
        return;
      }
      last = now;
      const dt = Math.min(0.05, Math.max(0, elapsed / 1000));
      t += dt;
      const keep = frameRef.current(dt, t);
      if (keep === false) {
        wants = false;
        update();
        return;
      }
      raf = requestAnimationFrame(tick);
    };

    const observer = new IntersectionObserver(
      ([entry]) => {
        inView = entry.isIntersecting;
        update();
      },
      { rootMargin },
    );
    observer.observe(el);

    const onVisibility = () => update();
    document.addEventListener("visibilitychange", onVisibility);

    wakeRef.current = () => {
      wants = true;
      update();
    };

    update();

    return () => {
      stop();
      observer.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
      wakeRef.current = () => {};
    };
  }, [ref, enabled, fpsCap, rootMargin]);

  return useMemo(() => ({ wake }), [wake]);
}

// matchMedia based check. False on the server.
export function isCoarsePointer(): boolean {
  if (typeof window === "undefined" || typeof window.matchMedia !== "function") return false;
  return window.matchMedia("(pointer: coarse)").matches;
}

"use client";

import { useEffect, useState, type RefObject } from "react";
import { isCoarsePointer } from "./loop";

// Caps DPR at 1.5 on coarse pointers and 2 otherwise.
export function defaultMaxDpr(): number {
  return isCoarsePointer() ? 1.5 : 2;
}

// Sets the backing size for a CSS box and returns the DPR used.
export function sizeCanvas(
  canvas: HTMLCanvasElement,
  cssW: number,
  cssH: number,
  maxDpr: number = defaultMaxDpr(),
): number {
  const dpr = Math.min(typeof window !== "undefined" ? window.devicePixelRatio || 1 : 1, maxDpr);
  canvas.width = Math.max(1, Math.round(cssW * dpr));
  canvas.height = Math.max(1, Math.round(cssH * dpr));
  canvas.style.width = `${cssW}px`;
  canvas.style.height = `${cssH}px`;
  return dpr;
}

// Rounded size of an element, kept current with a ResizeObserver.
export function useElementSize(ref: RefObject<HTMLElement | null>): { width: number; height: number } {
  const [size, setSize] = useState({ width: 0, height: 0 });

  useEffect(() => {
    const el = ref.current;
    if (!el || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver((entries) => {
      const box = entries[0]?.contentRect;
      if (!box) return;
      const width = Math.round(box.width);
      const height = Math.round(box.height);
      setSize((prev) => (prev.width === width && prev.height === height ? prev : { width, height }));
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, [ref]);

  return size;
}

